def _mixture_softmax_kernel(x_ref, w_ref, o_ref):
    # The weight is constant across the reduction axis, so sum first and
    # weight once afterward. Accumulation remains in float32.
    channel_sum = jnp.sum(x_ref[...], axis=1, dtype=jnp.float32)
    weight = w_ref[0, 0].astype(jnp.float32)
    o_ref[...] = (channel_sum * weight).astype(o_ref.dtype)


@jax.jit
def workload(x, w):
    batch, channels, height, width = x.shape
    if height % 16 == 0:
        block_h = 16
    elif height % 8 == 0:
        block_h = 8
    else:
        block_h = height

    w4 = w.reshape(1, height, 1, 1)
    return pl.pallas_call(
        _mixture_softmax_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, height, width), x.dtype),
        grid=(batch, height // block_h),
        in_specs=[
            pl.BlockSpec(
                (1, channels, block_h, width),
                lambda b, h: (b, 0, h, 0),
            ),
            pl.BlockSpec(
                (1, 1, block_h, 1),
                lambda b, h: (0, 0, h, 0),
            ),
        ],
        out_specs=pl.BlockSpec(
            (1, block_h, width),
            lambda b, h: (b, h, 0),
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(x, w4)

